    private static final class FilesystemFixture {
        final Path parent,root,file;
        final AgentRuntimeV2PrivateMysqlFixture.DirectoryPin parentPin,rootPin;
        FilesystemFixture() throws Exception {
            parent=Files.createTempDirectory(Path.of(System.getProperty("java.io.tmpdir")),"mysql-selector-parent-",PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));
            root=Files.createDirectory(parent.resolve("root"),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));file=root.resolve("private-mysql.properties");
            parentPin=pin(parent);rootPin=pin(root);
        }
        static AgentRuntimeV2PrivateMysqlFixture.DirectoryPin pin(Path directory) throws Exception {
            var a=Files.readAttributes(directory,"unix:dev,ino,uid,mode",java.nio.file.LinkOption.NOFOLLOW_LINKS);
            return new AgentRuntimeV2PrivateMysqlFixture.DirectoryPin((Long)a.get("dev"),(Long)a.get("ino"),(Integer)a.get("uid"),(Integer)a.get("mode")&07777);
        }
        void config() throws Exception {
            byte[] a=new byte[32],b=new byte[32];var random=new java.security.SecureRandom();random.nextBytes(a);random.nextBytes(b);
            String bytes=AgentRuntimeV2PrivateMysqlFixtureTest.config().replace("a".repeat(64),HexFormat.of().formatHex(a)).replace("b".repeat(64),HexFormat.of().formatHex(b));
            Files.writeString(file,bytes,java.nio.file.StandardOpenOption.CREATE_NEW);Files.setPosixFilePermissions(file,PosixFilePermissions.fromString("rw-------"));
        }
        Optional<String> read(java.util.function.Consumer<String> phase) throws Exception {return AgentRuntimeV2PrivateMysqlFixture.readPinnedConfiguration(root,parentPin,rootPin,1001,phase);}
    }
