    @Test void actualFilesystemRejectsWrongPinsKindsModesAndOwnerWithoutMockedAttributes() throws Exception {
        var wrongPin=new FilesystemFixture();wrongPin.config();
        var pin=new AgentRuntimeV2PrivateMysqlFixture.DirectoryPin(wrongPin.rootPin.dev(),wrongPin.rootPin.inode()+1,1001,0700);
        assertThrows(SecurityException.class,()->AgentRuntimeV2PrivateMysqlFixture.readPinnedConfiguration(wrongPin.root,wrongPin.parentPin,pin,1001,phase->{}));
        var mode=new FilesystemFixture();mode.config();Files.setPosixFilePermissions(mode.file,PosixFilePermissions.fromString("rw-r--r--"));assertThrows(SecurityException.class,()->mode.read(phase->{}));
        var owner=new FilesystemFixture();owner.config();
        // Actual opened uid1001 against a different trusted required uid. No
        // privilege escalation/chown of another user's inode or identity mock.
        assertThrows(SecurityException.class,()->AgentRuntimeV2PrivateMysqlFixture.readPinnedConfiguration(owner.root,owner.parentPin,owner.rootPin,1002,phase->{}));
        var kind=new FilesystemFixture();Files.createDirectory(kind.file);assertThrows(SecurityException.class,()->kind.read(phase->{}));
        var dangling=new FilesystemFixture();Files.createSymbolicLink(dangling.file,Path.of("absent-target"));assertThrows(SecurityException.class,()->dangling.read(phase->{}));
        var rootMode=new FilesystemFixture();Files.setPosixFilePermissions(rootMode.root,PosixFilePermissions.fromString("rwxr-xr-x"));assertThrows(SecurityException.class,()->rootMode.read(phase->{}));
    }
